from sympy import Matrix, symbols
try:
    Matrix([[1,2],[2,4],[3,6]]).LUdecomposition_Simple(rankcheck=True); print('bad')
except ValueError: print('OK tall deficient')
x = symbols('x')
# symbolic, singular only after cancellation in last row
M = Matrix([[1, x],[x, x**2]])
try:
    M.LUdecomposition_Simple(rankcheck=True); print('bad sym')
except ValueError: print('OK symbolic')
# zero matrix
try:
    Matrix.zeros(3,3).LUdecomposition_Simple(rankcheck=True); print('bad zeros')
except ValueError: print('OK zeros')
print(Matrix.eye(3).LUdecomposition_Simple(rankcheck=True))
" 2>/dev/null

